<?php
/**
 * cron_reminders.php
 *
 * Sends appointment reminder emails with a one-click cancel link.
 * Uses the existing `verification` table for both:
 *   - task = 'reminder_sent'      → dedup sentinel (prevents double-send)
 *   - task = 'cancel_appointment' → cancel token (generated by get_or_create_cancel_token)
 *
 * No new tables required.
 *
 * Cron example (every 30 min — script self-gates to the configured hour window):
 *   30 * * * * curl -s "https://your-site/cron_reminders.php?key=YOUR_CRON_KEY"
 *
 * Settings consumed:
 *   reminder_enabled      – '1' to enable
 *   reminder_days_before  – integer days ahead to look (default 1)
 *   reminder_time         – HH:MM server time for the send window (default '09:00')
 */

declare(strict_types=1);

require_once __DIR__ . '/functions.php';

header('Content-Type: application/json; charset=utf-8');

// ── Auth ──────────────────────────────────────────────────────────────────────
$cronKey  = (string) get_setting('cron_key', '');
$supplied = trim((string) ($_GET['key'] ?? $_SERVER['HTTP_X_CRON_KEY'] ?? ''));

if ($cronKey !== '') {
    if (!hash_equals($cronKey, $supplied)) {
        http_response_code(403);
        echo json_encode(['error' => 'forbidden']);
        exit;
    }
} elseif (PHP_SAPI !== 'cli') {
    http_response_code(403);
    echo json_encode(['error' => 'cron_key not configured — set it in settings or run from CLI']);
    exit;
}

// ── Feature gates ─────────────────────────────────────────────────────────────
if ((int) get_setting('reminder_enabled', '0') !== 1) {
    echo json_encode(['ok' => true, 'skipped' => true, 'reason' => 'reminders disabled']);
    exit;
}

if (!email_transport_is_ready()) {
    echo json_encode(['ok' => false, 'error' => 'SMTP not configured or PHPMailer files missing']);
    exit;
}

// ── Timing gate — only send during the configured hour window ─────────────────
$reminderTime = trim((string) get_setting('reminder_time', '09:00'));
$daysBefore   = max(0, (int) get_setting('reminder_days_before', '1'));
$reminderMessage = trim((string) get_setting('reminder_email_message', ''));  

$tz  = new DateTimeZone(get_app_timezone_name());
$now = new DateTimeImmutable('now', $tz);

[$rHour, $rMin] = array_pad(explode(':', $reminderTime), 2, '00');
$windowStart = new DateTimeImmutable(
    $now->format('Y-m-d') . ' ' . sprintf('%02d:%02d:00', (int)$rHour, (int)$rMin),
    $tz
);
$windowEnd = $windowStart->modify('+59 minutes +59 seconds');

if ($now < $windowStart || $now > $windowEnd) {
    echo json_encode([
        'ok'      => true,
        'skipped' => true,
        'reason'  => 'outside send window',
        'window'  => $windowStart->format('H:i') . '–' . $windowEnd->format('H:i'),
        'now'     => $now->format('H:i:s'),
    ]);
    exit;
}

// ── Find eligible appointments ────────────────────────────────────────────────
// Target: appointments on (today + daysBefore) that have NOT yet had a
// 'reminder_sent' row inserted into the verification table.
$targetDate  = $now->modify("+{$daysBefore} days")->format('Y-m-d');
$targetStart = $targetDate . ' 00:00:00';
$targetEnd   = $targetDate . ' 23:59:59';

$db = get_db();

$stmt = $db->prepare("
    SELECT
        a.id, a.customer_id, a.provider_id, a.appointment_type_id,
        a.start_time, a.end_time, a.status,
        c.email     AS customer_email,
        c.full_name AS customer_name
    FROM appointments a
    INNER JOIN customers c ON c.id = a.customer_id
    WHERE a.start_time BETWEEN ? AND ?
      AND a.status IN ('booked', 'confirmed', 'unconfirmed')
      AND c.email IS NOT NULL AND c.email != ''
      AND (c.email_invalid IS NULL OR c.email_invalid = 0)
      AND NOT EXISTS (
          SELECT 1 FROM verification v
          WHERE v.appointment_id = a.id
            AND v.task = 'reminder_sent'
      )
    ORDER BY a.start_time ASC
");
$stmt->execute([$targetStart, $targetEnd]);
$appointments = $stmt->fetchAll(PDO::FETCH_ASSOC);

// ── Send loop ─────────────────────────────────────────────────────────────────
$siteName   = get_site_name();
$dateFormat = (string) get_setting('date_format', 'd/m/Y H:i');
$orgEmail   = trim((string) get_setting('organization_email', ''));
$orgPhone   = trim((string) get_setting('organization_number', ''));

$sent = $failed = 0;
$log  = [];

foreach ($appointments as $appt) {
    $apptId  = (int) $appt['id'];
    $toEmail = (string) $appt['customer_email'];
    $toName  = (string) $appt['customer_name'];

    if (!email_domain_has_mx($toEmail)) {
        mark_customer_email_invalid((int) $appt['customer_id'], 'Domain has no mail server (MX/A record)');
        $log[] = ['id' => $apptId, 'status' => 'skipped', 'reason' => 'invalid email domain'];
        continue;
    }

    $provider       = get_user_by_id((int) $appt['provider_id']);
    $apptType       = get_appointment_type_by_id((int) $appt['appointment_type_id']);
    $providerName   = format_appointment_person_name($provider ?? []);
    $typeName       = (string) ($apptType['name'] ?? 'Appointment');
    $startFormatted = format_app_datetime((string) $appt['start_time'], $dateFormat);

    // Cancel token — reuses verification table via get_or_create_cancel_token()
    $cancelToken = get_or_create_cancel_token($apptId);
    if ($cancelToken === null) {
        $log[]  = ['id' => $apptId, 'status' => 'failed', 'reason' => 'could not generate cancel token'];
        $failed++;
        continue;
    }

    $cancelUrl  = build_app_url('cancel_appointment.php', ['token' => $cancelToken]);
    $subjectDay = match(true) {
        $daysBefore === 0 => 'today',
        $daysBefore === 1 => 'tomorrow',
        default           => "in {$daysBefore} days",
    };
    $subject = "Reminder: your {$typeName} appointment is {$subjectDay}";

    $contactParts = [];
    if ($orgEmail !== '') $contactParts[] = '<a href="mailto:' . htmlspecialchars($orgEmail, ENT_QUOTES) . '">' . htmlspecialchars($orgEmail, ENT_QUOTES) . '</a>';
    if ($orgPhone !== '') $contactParts[] = htmlspecialchars($orgPhone, ENT_QUOTES);
    $contactLine = $contactParts ? ': ' . implode(' or ', $contactParts) : '.';

$bodyHtml = '
<div style="font-family:Inter,ui-sans-serif,system-ui,sans-serif;max-width:540px;margin:0 auto;color:#1d2433">
  <h2 style="font-size:1.5rem;margin:0 0 12px;letter-spacing:-0.02em">Appointment reminder</h2>
  <p style="color:#667085;margin:0 0 20px;line-height:1.6">Hi ' . htmlspecialchars($toName, ENT_QUOTES) . ', this is a reminder of your upcoming appointment.</p>
  <div style="background:rgba(36,87,255,.06);border:1px solid rgba(36,87,255,.18);border-radius:14px;padding:18px;margin-bottom:24px">
    <table style="width:100%;border-collapse:collapse">
      <tr><td style="padding:5px 0;color:#667085;font-size:.85rem;width:110px">Appointment</td><td style="font-weight:700;padding:5px 0">' . htmlspecialchars($typeName, ENT_QUOTES) . '</td></tr>
      <tr><td style="padding:5px 0;color:#667085;font-size:.85rem">Provider</td><td style="font-weight:700;padding:5px 0">' . htmlspecialchars($providerName, ENT_QUOTES) . '</td></tr>
      <tr><td style="padding:5px 0;color:#667085;font-size:.85rem">Date &amp; Time</td><td style="font-weight:700;padding:5px 0">' . htmlspecialchars($startFormatted, ENT_QUOTES) . '</td></tr>
    </table>
  </div>'
  . ($reminderMessage !== '' ? '<p style="color:#1d2433;margin:0 0 20px;line-height:1.6">' . nl2br(htmlspecialchars($reminderMessage, ENT_QUOTES)) . '</p>' : '') . '
  <p style="color:#667085;margin:0 0 20px;line-height:1.6">Need to cancel? Use the button below. Cancel links expire 1 hour before your appointment time.</p>
  <a href="' . htmlspecialchars($cancelUrl, ENT_QUOTES) . '"
     style="display:inline-block;background:linear-gradient(135deg,#ef4444,#d92d20);color:#fff;text-decoration:none;border-radius:999px;padding:13px 22px;font-weight:700;font-size:.95rem">
    Cancel this appointment
  </a>
  <p style="color:#a8b3c7;font-size:.82rem;margin:28px 0 0;line-height:1.6">
    If you did not make this appointment or this email is in error, please contact us' . $contactLine . '
  </p>
</div>';

    $bodyPlain = "Appointment reminder\n\n"
        . "Hi {$toName}, this is a reminder of your upcoming appointment.\n\n"
        . "Appointment: {$typeName}\n"
        . "Provider: {$providerName}\n"
        . "Date & Time: {$startFormatted}\n\n"
        . ($reminderMessage !== '' ? "{$reminderMessage}\n\n" : '')
        . "To cancel your appointment visit:\n{$cancelUrl}\n\n"
        . ($orgEmail !== '' ? "Questions? Contact us: {$orgEmail}" . ($orgPhone !== '' ? " / {$orgPhone}" : '') . "\n" : '');
        
    $sendResult = send_email($toEmail, $subject, $bodyHtml, $bodyPlain);

    if ($sendResult === true) {
        // Mark as sent — a sentinel row in verification, no code needed for lookup,
        // but code must be unique so we use a hash of appointment_id + task.
        // expires_at is NULL so it never expires (we want the record to persist).
        $sentCode = hash('sha256', 'reminder_sent:' . $apptId);
        $db->prepare("
            INSERT IGNORE INTO verification (user_id, appointment_id, code, task, expires_at)
            VALUES (NULL, ?, ?, 'reminder_sent', NULL)
        ")->execute([$apptId, $sentCode]);

        $log[]  = ['id' => $apptId, 'status' => 'sent', 'to' => $toEmail];
        $sent++;
    } else {
        $log[]  = ['id' => $apptId, 'status' => 'failed', 'to' => $toEmail];
        $failed++;
    }
}

echo json_encode([
    'ok'     => true,
    'target' => $targetDate,
    'sent'   => $sent,
    'failed' => $failed,
    'log'    => $log,
]);